/// Verifies `token` against `keys` at `now` (Unix seconds).
pub fn verify_with_keys(
    token: &str,
    keys: &Jwks,
    expect: &Expect,
    now: i64,
) -> Result<Claims, VerifyError> {
    let mut it = token.split('.');
    let (Some(h), Some(p), Some(s), None) = (it.next(), it.next(), it.next(), it.next()) else {
        return Err(VerifyError::Malformed("not three parts".into()));
    };
    let header: Header = serde_json::from_slice(&part(h, "header")?)
        .map_err(|_| VerifyError::Malformed("header is not JSON".into()))?;
    if !matches!(header.alg.as_str(), "ES256" | "EdDSA") {
        return Err(VerifyError::Algorithm(header.alg));
    }
    if expect
        .typ
        .as_deref()
        .is_some_and(|want| header.typ.as_deref() != Some(want))
    {
        return Err(VerifyError::Malformed("unexpected token type".into()));
    }
    let candidates: Vec<&Jwk> = keys
        .keys
        .iter()
        .filter(|k| header.kid.is_empty() || k.kid == header.kid)
        .collect();
    if candidates.is_empty() {
        return Err(VerifyError::UnknownKey(header.kid));
    }
    let sig = part(s, "signature")?;
    let signed = format!("{h}.{p}");
    if !candidates
        .iter()
        .any(|k| verify_signature(k, &header.alg, signed.as_bytes(), &sig).is_ok())
    {
        return Err(VerifyError::Signature);
    }
    let claims: Map<String, Value> = serde_json::from_slice(&part(p, "payload")?)
        .map_err(|_| VerifyError::Malformed("payload is not a JSON object".into()))?;
    let leeway = expect.leeway.as_secs() as i64;
    let num = |k: &str| claims.get(k).and_then(Value::as_i64);
    match num("exp") {
        Some(exp) if exp + leeway > now => {}
        _ => return Err(VerifyError::Expired),
    }
    if num("nbf").is_some_and(|nbf| nbf - leeway > now)
        || num("iat").is_some_and(|iat| iat - leeway > now)
    {
        return Err(VerifyError::Expired);
    }
    let iss = claims
        .get("iss")
        .and_then(Value::as_str)
        .unwrap_or_default();
    if iss.trim_end_matches('/') != expect.issuer {
        return Err(VerifyError::Issuer(iss.to_string()));
    }
    let auds: Vec<&str> = match claims.get("aud") {
        Some(Value::String(a)) => vec![a.as_str()],
        Some(Value::Array(a)) => a.iter().filter_map(Value::as_str).collect(),
        _ => vec![],
    };
    if expect.audiences.is_empty() || !auds.iter().any(|a| expect.audiences.iter().any(|e| e == a))
    {
        return Err(VerifyError::Audience);
    }
    Ok(Claims(claims))
}

fn now_unix() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

/// Verifies tokens against the issuer's published key set, cached. An
/// unknown `kid` refetches the set at once, but at most once every
/// [`Verifier::MIN_REFETCH`] (so key rotation is picked up and a flood of bad
/// `kid`s cannot hammer the issuer).
#[cfg(feature = "http")]
pub struct Verifier {
    expect: Expect,
    jwks_url: String,
    http: reqwest::Client,
    cache: tokio::sync::RwLock<Option<(Jwks, std::time::Instant)>>,
    last_forced: std::sync::Mutex<Option<std::time::Instant>>,
}

#[cfg(feature = "http")]
impl Verifier {
    /// Keys are kept this long before a refresh.
    pub const TTL: Duration = Duration::from_secs(600);
    /// The shortest interval between two refetches caused by an unknown `kid`.
    pub const MIN_REFETCH: Duration = Duration::from_secs(30);

    /// Keys from `{issuer}/v1/oauth/jwks.json`.
    pub fn new(expect: Expect) -> Verifier {
        let url = format!("{}/v1/oauth/jwks.json", expect.issuer);
        Verifier::with_jwks_url(expect, url)
    }

    /// Verifies callback receipts for `callback_url` against
    /// [`CALLBACK_RECEIPT_JWKS_URL`]. Check replay with [`ReplayGuard`].
    pub fn callback(callback_url: impl Into<String>) -> Verifier {
        Verifier::with_jwks_url(Expect::callback(callback_url), CALLBACK_RECEIPT_JWKS_URL)
    }

    pub fn with_jwks_url(expect: Expect, jwks_url: impl Into<String>) -> Verifier {
        Verifier {
            expect,
            jwks_url: jwks_url.into(),
            http: reqwest::Client::builder()
                .timeout(Duration::from_secs(10))
                .build()
                .expect("a reqwest client"),
            cache: tokio::sync::RwLock::new(None),
            last_forced: std::sync::Mutex::new(None),
        }
    }

    async fn keys(&self, force: bool) -> Result<Jwks, VerifyError> {
        if let Some((k, at)) = self.cache.read().await.as_ref() {
            let fresh = at.elapsed() < Verifier::TTL;
            let throttled = force && {
                let mut last = self.last_forced.lock().unwrap_or_else(|e| e.into_inner());
                let recent = last.is_some_and(|t| t.elapsed() < Verifier::MIN_REFETCH);
                if !recent {
                    *last = Some(std::time::Instant::now());
                }
                recent
            };
            if fresh && (!force || throttled) {
                return Ok(k.clone());
            }
        }
        let fetched: Jwks = self
            .http
            .get(&self.jwks_url)
            .send()
            .await
            .and_then(|r| r.error_for_status())
            .map_err(|e| VerifyError::Keys(e.to_string()))?
            .json()
            .await
            .map_err(|e| VerifyError::Keys(e.to_string()))?;
        *self.cache.write().await = Some((fetched.clone(), std::time::Instant::now()));
        Ok(fetched)
    }

    pub async fn verify(&self, token: &str) -> Result<Claims, VerifyError> {
        let keys = self.keys(false).await?;
        match verify_with_keys(token, &keys, &self.expect, now_unix()) {
            Err(VerifyError::UnknownKey(_)) => {
                let keys = self.keys(true).await?;
                verify_with_keys(token, &keys, &self.expect, now_unix())
            }
            other => other,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use p256::ecdsa::signature::Signer as _;
    use serde_json::json;

    fn b64(v: &[u8]) -> String {
        URL_SAFE_NO_PAD.encode(v)
    }

    fn es256() -> (p256::ecdsa::SigningKey, Jwk) {
        let sk = p256::ecdsa::SigningKey::from_slice(&[7u8; 32]).unwrap();
        let pt = sk.verifying_key().to_encoded_point(false);
        let jwk = Jwk {
            kid: "k1".into(),
            kty: "EC".into(),
            crv: "P-256".into(),
            x: b64(pt.x().unwrap()),
            y: b64(pt.y().unwrap()),
            alg: Some("ES256".into()),
            use_: Some("sig".into()),
        };
        (sk, jwk)
    }

    fn sign_es(sk: &p256::ecdsa::SigningKey, header: Value, claims: Value) -> String {
        let signed = format!(
            "{}.{}",
            b64(header.to_string().as_bytes()),
            b64(claims.to_string().as_bytes())
        );
        let sig: p256::ecdsa::Signature = sk.sign(signed.as_bytes());
        format!("{signed}.{}", b64(&sig.to_bytes()))
    }

    const NOW: i64 = 1_800_000_000;

    fn good() -> Value {
        json!({"iss": "https://api.sylphx.com", "aud": ["app"], "sub": "u1", "exp": NOW + 300, "iat": NOW - 10})
    }

    fn expect() -> Expect {
        Expect::issuer("https://api.sylphx.com").audience("app")
    }

    #[test]
    fn a_valid_es256_token_verifies() {
        let (sk, jwk) = es256();
        let keys = Jwks { keys: vec![jwk] };
        let t = sign_es(&sk, json!({"alg": "ES256", "kid": "k1"}), good());
        let c = verify_with_keys(&t, &keys, &expect(), NOW).unwrap();
        assert_eq!(c.subject(), Some("u1"));
        assert_eq!(key_id(&t).unwrap(), "k1");
    }

    #[test]
    fn a_valid_eddsa_token_verifies() {
        use ed25519_dalek::Signer as _;
        let sk = ed25519_dalek::SigningKey::from_bytes(&[9u8; 32]);
        let keys = Jwks {
            keys: vec![Jwk {
                kid: "e1".into(),
                kty: "OKP".into(),
                crv: "Ed25519".into(),
                x: b64(sk.verifying_key().as_bytes()),
                y: String::new(),
                alg: None,
                use_: None,
            }],
        };
        let signed = format!(
            "{}.{}",
            b64(json!({"alg": "EdDSA", "kid": "e1"}).to_string().as_bytes()),
            b64(good().to_string().as_bytes())
        );
        let t = format!("{signed}.{}", b64(&sk.sign(signed.as_bytes()).to_bytes()));
        assert!(verify_with_keys(&t, &keys, &expect(), NOW).is_ok());
    }

    #[test]
    fn an_empty_audience_list_refuses_every_token() {
        let (sk, jwk) = es256();
        let keys = Jwks { keys: vec![jwk] };
        let t = sign_es(&sk, json!({"alg": "ES256", "kid": "k1"}), good());
        let none = Expect::issuer("https://api.sylphx.com");
        assert_eq!(
            verify_with_keys(&t, &keys, &none, NOW).unwrap_err(),
            VerifyError::Audience
        );
    }

    #[test]
    fn hostile_tokens_are_refused() {
        let (sk, jwk) = es256();
        let keys = Jwks { keys: vec![jwk] };
        let h = json!({"alg": "ES256", "kid": "k1"});
        let with = |f: &dyn Fn(&mut Map<String, Value>)| {
            let mut c = good().as_object().unwrap().clone();
            f(&mut c);
            sign_es(&sk, h.clone(), Value::Object(c))
        };
        let cases: Vec<(&str, String, fn(&VerifyError) -> bool)> = vec![
            (
                "expired",
                with(&|c| {
                    c.insert("exp".into(), json!(NOW - 120));
                }),
                |e| *e == VerifyError::Expired,
            ),
            (
                "no exp",
                with(&|c| {
                    c.remove("exp");
                }),
                |e| *e == VerifyError::Expired,
            ),
            (
                "not yet valid",
                with(&|c| {
                    c.insert("nbf".into(), json!(NOW + 600));
                }),
                |e| *e == VerifyError::Expired,
            ),
            (
                "other issuer",
                with(&|c| {
                    c.insert("iss".into(), json!("https://evil.example"));
                }),
                |e| matches!(e, VerifyError::Issuer(_)),
            ),
            (
                "other audience",
                with(&|c| {
                    c.insert("aud".into(), json!("other"));
                }),
                |e| *e == VerifyError::Audience,
            ),
            (
                "alg none",
                format!(
                    "{}.{}.",
                    b64(br#"{"alg":"none"}"#),
                    b64(good().to_string().as_bytes())
                ),
                |e| matches!(e, VerifyError::Algorithm(_)),
            ),
            (
                "alg HS256",
                format!(
                    "{}.{}.x",
                    b64(br#"{"alg":"HS256","kid":"k1"}"#),
                    b64(good().to_string().as_bytes())
                ),
                |e| matches!(e, VerifyError::Algorithm(_)),
            ),
            (
                "unknown kid",
                sign_es(&sk, json!({"alg": "ES256", "kid": "zz"}), good()),
                |e| matches!(e, VerifyError::UnknownKey(_)),
            ),
            ("two parts", "a.b".into(), |e| {
                matches!(e, VerifyError::Malformed(_))
            }),
            ("garbage", "!!.!!.!!".into(), |e| {
                matches!(e, VerifyError::Malformed(_))
            }),
        ];
        for (name, token, ok) in cases {
            let e = verify_with_keys(&token, &keys, &expect(), NOW).expect_err(name);
            assert!(ok(&e), "{name}: {e:?}");
        }
        // A payload swapped under a valid signature.
        let t = sign_es(&sk, h.clone(), good());
        let mut parts: Vec<&str> = t.split('.').collect();
        let forged = b64(json!({"iss": "https://api.sylphx.com", "aud": "app", "sub": "admin", "exp": NOW + 300}).to_string().as_bytes());
        parts[1] = &forged;
        assert_eq!(
            verify_with_keys(&parts.join("."), &keys, &expect(), NOW),
            Err(VerifyError::Signature)
        );
        // A key from another issuer set under the same kid.
        let other = p256::ecdsa::SigningKey::from_slice(&[8u8; 32]).unwrap();
        let t = sign_es(&other, h.clone(), good());
        assert_eq!(
            verify_with_keys(&t, &keys, &expect(), NOW),
            Err(VerifyError::Signature)
        );
        // Leeway: 30 s past exp is still inside the default 60 s.
        let t = with(&|c| {
            c.insert("exp".into(), json!(NOW - 30));
        });
        assert!(verify_with_keys(&t, &keys, &expect(), NOW).is_ok());
    }

    fn receipt(
        sk: &ed25519_dalek::SigningKey,
        kid: &str,
        aud: &str,
        jti: &str,
        exp: i64,
    ) -> String {
        use ed25519_dalek::Signer as _;
        let signed = format!(
            "{}.{}",
            b64(json!({"alg": "EdDSA", "typ": "compute-tick-receipt+jwt", "kid": kid}).to_string().as_bytes()),
            b64(json!({"iss": CALLBACK_RECEIPT_ISSUER, "aud": aud, "jti": jti, "iat": NOW, "nbf": NOW, "exp": exp}).to_string().as_bytes())
        );
        format!("{signed}.{}", b64(&sk.sign(signed.as_bytes()).to_bytes()))
    }

    #[test]
    fn a_callback_receipt_verifies_for_its_url_once() {
        let sk = ed25519_dalek::SigningKey::from_bytes(&[5u8; 32]);
        // The shape the Compute JWKS publishes, extra fields included.
        let keys: Jwks = serde_json::from_value(json!({"keys": [{
            "issuer": CALLBACK_RECEIPT_ISSUER, "typ": "compute-tick-receipt+jwt",
            "kty": "OKP", "crv": "Ed25519", "alg": "EdDSA", "use": "sig", "kid": "cb-1",
            "x": b64(sk.verifying_key().as_bytes()),
            "not_before_unix_seconds": 0, "not_after_unix_seconds": 4_102_444_800i64
        }]}))
        .unwrap();
        let url = "https://hooks.example.com/task";
        let guard = ReplayGuard::new();
        let t = receipt(&sk, "cb-1", url, "s:2026:t1", NOW + 300);
        let c = verify_callback_with_keys(&t, &keys, url, &guard, NOW).unwrap();
        assert_eq!(c.jti(), Some("s:2026:t1"));
        // The same receipt again is a replay, until it has expired.
        assert_eq!(
            verify_callback_with_keys(&t, &keys, url, &guard, NOW + 5),
            Err(VerifyError::Replayed)
        );
        // A receipt for another URL is not for this receiver.
        let other = receipt(
            &sk,
            "cb-1",
            "https://evil.example.com/x",
            "s:2026:t2",
            NOW + 300,
        );
        assert_eq!(
            verify_callback_with_keys(&other, &keys, url, &guard, NOW),
            Err(VerifyError::Audience)
        );
        // Expired (past the leeway) is refused before replay is considered.
        let old = receipt(&sk, "cb-1", url, "s:2026:t3", NOW - 120);
        assert_eq!(
            verify_callback_with_keys(&old, &keys, url, &guard, NOW),
            Err(VerifyError::Expired)
        );
        // Rotation: a key set holding both keys verifies a receipt of either.
        let sk2 = ed25519_dalek::SigningKey::from_bytes(&[6u8; 32]);
        let mut both = keys.clone();
        both.keys.push(Jwk {
            kid: "cb-2".into(),
            kty: "OKP".into(),
            crv: "Ed25519".into(),
            x: b64(sk2.verifying_key().as_bytes()),
            y: String::new(),
            alg: Some("EdDSA".into()),
            use_: Some("sig".into()),
        });
        let t2 = receipt(&sk2, "cb-2", url, "s:2026:t4", NOW + 300);
        assert!(verify_callback_with_keys(&t2, &both, url, &guard, NOW).is_ok());
        // A jti stays remembered through exp + leeway, forgotten after.
        let t5 = receipt(&sk, "cb-1", url, "s:2026:t5", NOW + 10);
        assert!(verify_callback_with_keys(&t5, &keys, url, &guard, NOW).is_ok());
        assert_eq!(
            verify_callback_with_keys(&t5, &keys, url, &guard, NOW + 35),
            Err(VerifyError::Replayed)
        );
        // A token of another type is refused.
        let signed = format!(
            "{}.{}",
            b64(json!({"alg": "EdDSA", "kid": "cb-1"})
                .to_string()
                .as_bytes()),
            b64(
                json!({"iss": CALLBACK_RECEIPT_ISSUER, "aud": url, "jti": "x", "exp": NOW + 300})
                    .to_string()
                    .as_bytes()
            )
        );
        use ed25519_dalek::Signer as _;
        let untyped = format!("{signed}.{}", b64(&sk.sign(signed.as_bytes()).to_bytes()));
        assert!(matches!(
            verify_callback_with_keys(&untyped, &keys, url, &guard, NOW),
            Err(VerifyError::Malformed(_))
        ));
    }
}
